INSERT INTO t_p69702834_empty_site_creation_.converted_files (title, description, file_url, file_name, s3_key, size_bytes)
VALUES ('Номенклатура ВГ-ТРЕЙД счёт 1295 от 31.10 в загрузку 1С',
 'По правилу «Создание номенклатуры в 1С через OData» из счёта № 1295 от 31.10.2026 (ВГ-ТРЕЙД). 234 строки, 1 744 673,80 руб. — сходится с итогом. После объединения дублей по артикулу 228 товаров, порядок как в счёте. Штрихкоды у всех, общих нет. Цена — из счёта за 1 шт; у двух дублей цены разные (437842: 4 462,00 и 4 462,20; 441993: 1 456,20 и 1 618,20) — взята большая. Вес и ТН ВЭД из каталога по артикулу: без веса 38, без ТН ВЭД 16. Бренд: Weissgauff 225, Xiaomi 3.',
 '/converted/nomenklatura-vg-treyd-schet-1295-31-10-v-zagruzku-1s.xlsx', 'Номенклатура ВГ-ТРЕЙД счёт 1295 от 31.10 в загрузку 1С.xlsx', '', 19993);